// Type declarations for font file imports with { type: "file" }
// Bun resolves these to file paths at dev time, $bunfs/ paths when compiled
declare module "@fontsource/inter/files/inter-latin-400-normal.woff" {
  const path: string;
  export default path;
}
declare module "@fontsource/inter/files/inter-latin-600-normal.woff" {
  const path: string;
  export default path;
}
declare module "@fontsource/inter/files/inter-latin-900-normal.woff" {
  const path: string;
  export default path;
}
declare module "@fontsource/fraunces/files/fraunces-latin-300-normal.woff" {
  const path: string;
  export default path;
}
declare module "@fontsource/fraunces/files/fraunces-latin-400-normal.woff" {
  const path: string;
  export default path;
}
declare module "@fontsource/newsreader/files/newsreader-latin-400-normal.woff" {
  const path: string;
  export default path;
}
